'use strict';
(function(root){
const A=root.DCAccountCore,$=id=>document.getElementById(id),categories=[['all','全部'],['suits','🧩 套装'],['characters','👤 角色'],['props','🎁 道具'],['skins','🎨 皮肤'],['pieces','💎 碎片'],['personal','✨ 个性化']],paths={main:'/api/User/GetMyBagNew',props:'/api/User/GetMyBagProp',pieces:'/api/User/GetMyBagPiece',suits:'/api/User/GetMyBagSuit'},types={23:['characters','角色'],13:['props','奖励歌曲'],9:['props','隐藏歌曲'],22:['props','宝箱'],19:['skins','边框'],7:['skins','游戏皮肤'],6:['skins','光标'],20:['skins','滑条'],8:['personal','头像框'],16:['personal','判定字体'],27:['personal','满分特效'],12:['personal','称号']};
const categoryColors={all:'#b4a4ce',suits:'#be97f4',characters:'#75b9f0',props:'#e8ad69',skins:'#56cbbb',pieces:'#e58abd',personal:'#e8cf73',other:'#9aa6b8'};
function classify(item,source){if(source==='suits')return{group:'suits',label:'套装'};if(source==='pieces')return{group:'pieces',label:{1:'装饰碎片',2:'角色碎片',3:'活动碎片'}[Number(item.PieceType)]||'未分类碎片'};const value=types[Number(item.ResourceType)];if(value?.[0]==='characters'&&item.IsInPieces)return{group:'pieces',label:'角色碎片'};return value?{group:value[0],label:value[1]}:{group:source==='props'?'props':'other',label:item.ResourceTypeText||'其他资源'};}
function title(item){return String(item.ResourceName||item.PieceName||item.SuitName||item.Name||'未命名道具');}
function imageURL(item){return A.mediaURL(item.PicPath)||A.mediaURL(item.ResourcePath);}
function extension(bytes,url){if(bytes[0]===0x47&&bytes[1]===0x49&&bytes[2]===0x46)return'gif';if(bytes[0]===0x89&&bytes[1]===0x50&&bytes[2]===0x4e)return'png';if(bytes[0]===0xff&&bytes[1]===0xd8)return'jpg';if(new TextDecoder().decode(bytes.slice(8,12))==='WEBP')return'webp';return new URL(url).pathname.match(/\.(png|gif|jpe?g|webp|avif)$/i)?.[1]||'bin';}
async function render(h){const{request,esc:e,body,status,cache,isCurrent,download}=h;let selected='all',version=0,entries=[];cache.resourceSources=cache.resourceSources||{};body().innerHTML=`<div class="account-list-heading"><h4>道具与装扮</h4><button id="resourcesRefresh">刷新已选分类</button></div><nav id="resourceCategories" class="resource-categories" aria-label="道具一级分类">${categories.map(([id,label])=>`<button data-resource-category="${id}" style="--resource-color:${categoryColors[id]}" class="${id==='all'?'active':''}">${label}</button>`).join('')}</nav><p class="field-hint">展示图完整保留比例与动画。下载的是官方提供的展示贴图；完整游戏资源包可能另有格式和权限。</p><div id="resourceProgress" role="status"></div><div id="resourceCards" class="resource-cards"></div>`;
function draw(){if(!isCurrent())return;const rows=entries.filter(x=>selected==='all'||x.category.group===selected);$('resourceCards').innerHTML=rows.length?rows.map((row,i)=>{const{item,category}=row,pic=imageURL(item),members=A.list(item.ListResource),owned=members.filter(x=>x.HasOwned).length;return`<article class="resource-card" data-resource-group="${category.group}" style="--resource-color:${categoryColors[category.group]||categoryColors.other}"><div class="resource-icon">${pic?`<img src="${e(pic)}" alt="${e(title(item))}" loading="lazy" referrerpolicy="no-referrer">`:'<span>◈</span>'}</div><div class="resource-info"><small>${e(categories.find(c=>c[0]===category.group)?.[1]||'其他')} · ${e(category.label)}</small><h5>${e(title(item))}</h5><p>${e(item.Intro||item.Description||'')}${item.Balance!==undefined?' · 数量 '+e(item.Balance):''}${members.length?' · 已拥有 '+owned+'/'+members.length:''}</p><div class="resource-actions">${pic?`<button data-resource-download="${i}">下载贴图</button><a href="${e(pic)}" target="_blank" rel="noopener noreferrer" class="text-button">原图 ↗</a>`:'<span class="field-hint">官方未提供展示图</span>'}${Number(item.ResourceType)===6&&item.ResourceID?`<button data-resource-preview="${i}">网页预览</button><button data-resource-apply="${i}">装备到机台</button>`:''}</div>${members.length?`<details><summary>套装部件 ${members.length}</summary><div class="suit-parts">${members.map(m=>`<span>${m.HasOwned?'☑':'☐'} ${e(title(m))}${imageURL(m)?` <a href="${e(imageURL(m))}" target="_blank" rel="noopener noreferrer">贴图 ↗</a>`:''}</span>`).join('')}</div></details>`:''}</div></article>`;}).join(''):'<div class="empty-state">当前分类暂无已返回的道具</div>';$('resourceCards').querySelectorAll('[data-resource-download]').forEach(b=>b.onclick=async()=>{const item=rows[+b.dataset.resourceDownload].item,url=imageURL(item);b.disabled=true;try{const result=await A.remoteFile({Url:url},h.fetchResource,{label:'道具展示图',max:20*1024*1024});if(!isCurrent())return;const ext=extension(result.data,url);download(new Blob([result.data],{type:ext==='jpg'?'image/jpeg':ext==='bin'?'application/octet-stream':'image/'+ext}),root.DCProject.fileName(title(item))+'.'+ext);status('已准备原始贴图下载，保留文件自身动画');}catch(err){status(err.message+'；也可点击该道具的“原图”自行保存');}finally{if(b.isConnected)b.disabled=false;}});$('resourceCards').querySelectorAll('[data-resource-preview]').forEach(b=>b.onclick=async()=>{const item=rows[+b.dataset.resourcePreview].item;b.disabled=true;try{status('正在读取光标详情与原始贴图…');const detail=await request('/api/User/GetBagItem',{params:{resourceId:Number(item.ResourceID)}});if(!isCurrent())return;const actual=detail?.Data&&typeof detail.Data==='object'?detail.Data:detail,url=A.mediaURL(actual?.ResourcePath)||A.mediaURL(actual?.PicPath)||A.mediaURL(item.ResourcePath)||imageURL(item);if(!url)throw Error('官方未返回可预览的贴图');const result=await A.remoteFile({Url:url},h.fetchResource,{label:'光标贴图',max:20*1024*1024}),ext=extension(result.data,url);if(ext==='bin')throw Error('该资源不是可解码的单张图片，暂不支持完整机器资源包');if(!isCurrent())return;await h.previewCursor({name:title(item),resourceId:Number(item.ResourceID),data:result.data,mime:ext==='jpg'?'image/jpeg':'image/'+ext});status('已用于本站外圈单押单点；等比例显示，多押和长条保留当前皮肤。未修改机台装备。');}catch(err){status('网页光标预览失败：'+err.message);}finally{if(b.isConnected)b.disabled=false;}});$('resourceCards').querySelectorAll('[data-resource-apply]').forEach(b=>b.onclick=async()=>{const item=rows[+b.dataset.resourceApply].item;b.disabled=true;try{await request('/api/User/Apply',{method:'PUT',params:{resourceId:Number(item.ResourceID)}});status('已提交使用 '+title(item));}catch(err){status(err.message);}finally{if(b.isConnected)b.disabled=false;}});}
async function load(force=false){const run=++version,sources=selected==='all'?['main','props','pieces','suits']:selected==='props'?['props']:selected==='pieces'?['pieces']:selected==='suits'?['suits']:['main'];let done=0,failures=[];for(const source of sources){if(!isCurrent()||run!==version)return;$('resourceProgress').innerHTML=`<progress max="${sources.length}" value="${done}"></progress><span>正在读取 ${done+1}/${sources.length} 个官方分类来源…</span>`;try{if(force||!cache.resourceSources[source])cache.resourceSources[source]=A.list(await request(paths[source]));}catch(err){failures.push(source+'：'+err.message);}done++;}if(!isCurrent()||run!==version)return;entries=Object.entries(cache.resourceSources).flatMap(([source,rows])=>rows.filter(item=>!(source==='main'&&Number(item.ResourceType)===23&&item.IsInPieces)).map(item=>({item,source,category:classify(item,source)})));draw();$('resourceProgress').textContent=failures.length?'已显示成功返回的分类；'+failures.join('；'):'分类加载完成 · '+entries.length+' 项';}
$('resourceCategories').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=b.dataset.resourceCategory;$('resourceCategories').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));load();});$('resourcesRefresh').onclick=()=>load(true);await load();}
root.DCAccountResources={render,classify,title,imageURL,extension,categoryColors};
})(typeof window==='undefined'?globalThis:window);
